    13→// blobIndexMask is a bitmask representing the set of blob indices that are currently set.
    14→type blobIndexMask []bool
    15→
    16→// BlobStorageSummary represents cached information about the BlobSidecars on disk for each root the cache knows about.
    17→type BlobStorageSummary struct {
    18→	epoch primitives.Epoch
    19→	mask  blobIndexMask
    20→}
    21→
    22→// HasIndex returns true if the BlobSidecar at the given index is available in the filesystem.
    23→func (s BlobStorageSummary) HasIndex(idx uint64) bool {
    24→	if idx >= uint64(len(s.mask)) {
    25→		return false
    26→	}
    27→	return s.mask[idx]
    28→}
    29→
    30→// AllAvailable returns true if we have all blobs for all indices from 0 to count-1.
    31→func (s BlobStorageSummary) AllAvailable(count int) bool {
    32→	if count > len(s.mask) {
    33→		return false
    34→	}
